const ACTIVITY_TYPES=['classroom','live_remote','hybrid_live','self_study_home','self_study_school','self_study_other','excursion','project','workshop','exam','practice','other'] as const;
type ActivityType=typeof ACTIVITY_TYPES[number];
const SUPERVISION=['instructor','remote_instructor','self_directed','external_supervisor','mixed','none'] as const;
const PLAN_STATUS=['draft','review','published','archived'] as const;

function isAdmin(auth:CoreAuthContext){return auth.isPlatformAdmin||auth.role==='tenant_admin';}
function requireManage(auth:CoreAuthContext){if(!isAdmin(auth)&&!hasPermission(auth,'courses.manage'))throw new Error('FORBIDDEN_EDUCATION_MANAGE');}
function requireContent(auth:CoreAuthContext){if(!isAdmin(auth)&&!hasPermission(auth,'content.manage'))throw new Error('FORBIDDEN_EDUCATION_CONTENT');}
function courseScope(auth:CoreAuthContext,courseId:string){if(!isAdmin(auth)&&!auth.courseIds.includes(courseId))throw new Error('FORBIDDEN_COURSE_SCOPE');}
function required(v:unknown,max=500){const s=safeString(v,max);if(!s)throw new Error('FIELD_REQUIRED');return s;}
function optional(v:unknown,max=8000){return safeString(v,max)||null;}
function bool(v:unknown){return v===true||v===1||String(v)==='1'?1:0;}
function oneOf<T extends readonly string[]>(v:unknown,values:T,fallback:T[number]):T[number]{const x=String(v||fallback);if(!values.includes(x as T[number]))throw new Error('ENUM_VALUE_INVALID');return x as T[number];}
function iso(v:unknown){const s=safeString(v,50);if(!s)return null;const d=new Date(s);if(Number.isNaN(d.getTime()))throw new Error('DATE_INVALID');return d.toISOString();}
function day(v:unknown){const s=safeString(v,20);if(!s)return null;if(!/^\d{4}-\d{2}-\d{2}$/.test(s))throw new Error('DATE_INVALID');return s;}
function two(n:number){return String(n).padStart(2,'0');}
function parseDate(v:unknown):string|null{if(v===null||v===undefined||v==='')return null;if(typeof v==='number'&&Number.isFinite(v)){const d=new Date(Date.UTC(1899,11,30)+Math.floor(v)*86400000);return d.toISOString().slice(0,10);}const s=String(v).trim();let m=s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);if(m)return`${m[1]}-${two(Number(m[2]))}-${two(Number(m[3]))}`;m=s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{2,4})/);if(m){let y=Number(m[3]);if(y<100)y+=2000;return`${y}-${two(Number(m[2]))}-${two(Number(m[1]))}`;}const d=new Date(s);return Number.isNaN(d.getTime())?null:d.toISOString().slice(0,10);}
function parseTime(v:unknown):string|null{if(v===null||v===undefined||v==='')return null;if(typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<1){const mins=Math.round(v*1440)%1440;return`${two(Math.floor(mins/60))}:${two(mins%60)}`;}const s=String(v).trim(),m=s.match(/(\d{1,2})[:.](\d{2})/);if(m&&Number(m[1])<24&&Number(m[2])<60)return`${two(Number(m[1]))}:${two(Number(m[2]))}`;return null;}
function overlap(aStart:string,aEnd:string,bStart:string,bEnd:string){return aStart<bEnd&&bStart<aEnd;}
async function sha256Text(value:string){const bytes=new TextEncoder().encode(value),hash=await crypto.subtle.digest('SHA-256',bytes);return[...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('');}
async function sha256Buffer(value:ArrayBuffer){const hash=await crypto.subtle.digest('SHA-256',value);return[...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('');}
async function exists(env:Env,sql:string,...args:unknown[]){return!!await env.DB.prepare(sql).bind(...args).first();}

export async function listCourseActivities(env:Env,auth:CoreAuthContext,tenantId:string,courseId:string){
  courseScope(auth,courseId);
  const rows=(await env.DB.prepare(`SELECT a.id,a.lesson_id,a.session_id,a.activity_type,a.location_label,a.supervision_mode,a.attendance_expected,a.evidence_required,a.task_text,a.expected_outcome,a.safety_notes,
    COALESCE(l.starts_at,s.starts_at) starts_at,COALESCE(l.ends_at,s.ends_at) ends_at,COALESCE(sub.name,s.subject) subject,COALESCE(t.name,s.instructor_text) teacher,COALESCE(l.room,s.room) room
    FROM instruction_activity_details a LEFT JOIN lessons l ON l.id=a.lesson_id AND l.tenant_id=a.tenant_id LEFT JOIN attendance_sessions s ON s.id=a.session_id AND s.tenant_id=a.tenant_id LEFT JOIN subjects sub ON sub.id=l.subject_id LEFT JOIN teachers t ON t.id=l.teacher_id WHERE a.tenant_id=? AND a.course_id=? ORDER BY starts_at`).bind(tenantId,courseId).all<Record<string,unknown>>()).results??[];
  if(auth.role==='participant'||auth.role==='class_admin'||auth.role==='guest')return rows.map(r=>({id:r.id,lesson_id:r.lesson_id,session_id:r.session_id,activity_type:r.activity_type,location_label:r.location_label,supervision_mode:r.supervision_mode,attendance_expected:r.attendance_expected,evidence_required:r.evidence_required,task_text:r.task_text,expected_outcome:r.expected_outcome,starts_at:r.starts_at,ends_at:r.ends_at,subject:r.subject,teacher:r.teacher,room:r.room}));
  return rows;
}

export async function saveActivityDetail(env:Env,auth:CoreAuthContext,tenantId:string,courseId:string,input:Record<string,unknown>){
  let allowed=isAdmin(auth)||hasPermission(auth,'content.manage');if(!allowed){try{await teacherAttendanceAuth(env,auth,tenantId,courseId);allowed=true;}catch{}}if(!allowed)throw new Error('FORBIDDEN_ACTIVITY_MANAGE');courseScope(auth,courseId);
  const lessonId=optional(input.lesson_id,120),sessionId=optional(input.session_id,120);if(!lessonId&&!sessionId)throw new Error('ACTIVITY_SOURCE_REQUIRED');if(lessonId&&!await exists(env,'SELECT 1 FROM lessons WHERE tenant_id=? AND course_id=? AND id=?',tenantId,courseId,lessonId))throw new Error('LESSON_NOT_FOUND');if(sessionId&&!await exists(env,'SELECT 1 FROM attendance_sessions WHERE tenant_id=? AND course_id=? AND id=?',tenantId,courseId,sessionId))throw new Error('ATTENDANCE_SESSION_NOT_FOUND');
  const type=oneOf(input.activity_type,ACTIVITY_TYPES,'classroom'),supervision=oneOf(input.supervision_mode,SUPERVISION,type.startsWith('self_study')?'self_directed':'instructor'),ts=nowIso();
  let row=lessonId?await env.DB.prepare('SELECT id FROM instruction_activity_details WHERE tenant_id=? AND lesson_id=?').bind(tenantId,lessonId).first<{id:string}>():await env.DB.prepare('SELECT id FROM instruction_activity_details WHERE tenant_id=? AND session_id=?').bind(tenantId,sessionId).first<{id:string}>();const activityId=row?.id||id('act_');
  if(row)await env.DB.prepare('UPDATE instruction_activity_details SET course_id=?,lesson_id=?,session_id=?,activity_type=?,location_label=?,supervision_mode=?,attendance_expected=?,evidence_required=?,task_text=?,expected_outcome=?,safety_notes=?,external_contact=?,updated_at=? WHERE tenant_id=? AND id=?').bind(courseId,lessonId,sessionId,type,optional(input.location_label,500),supervision,bool(input.attendance_expected??!type.startsWith('self_study')),bool(input.evidence_required),optional(input.task_text,8000),optional(input.expected_outcome,8000),optional(input.safety_notes,5000),optional(input.external_contact,1000),ts,tenantId,activityId).run();
  else await env.DB.prepare('INSERT INTO instruction_activity_details(id,tenant_id,course_id,lesson_id,session_id,activity_type,location_label,supervision_mode,attendance_expected,evidence_required,task_text,expected_outcome,safety_notes,external_contact,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(activityId,tenantId,courseId,lessonId,sessionId,type,optional(input.location_label,500),supervision,bool(input.attendance_expected??!type.startsWith('self_study')),bool(input.evidence_required),optional(input.task_text,8000),optional(input.expected_outcome,8000),optional(input.safety_notes,5000),optional(input.external_contact,1000),auth.userId,ts,ts).run();
  await audit(env.DB,auth.userId,'education.activity_saved',tenantId,courseId,'instruction_activity',activityId,{type,lessonId,sessionId});return{activity_id:activityId};
}

