  const values=[courseId,optional(input.lesson_id,120),required(input.title,300),required(input.destination,500),optional(input.meeting_point,500),starts,ends,optional(input.responsible_teacher_id,120),optional(input.external_contact,1000),optional(input.transport,1000),optional(input.learning_objective,6000),optional(input.safety_notes,6000),bool(input.consent_required),status,ts,tenantId,excursionId];
