export async function listTimetablePlans(env:Env,auth:CoreAuthContext,tenantId:string){requireManage(auth);return(await env.DB.prepare(`SELECT p.*,(SELECT COUNT(*) FROM timetable_plan_entries e WHERE e.tenant_id=p.tenant_id AND e.plan_id=p.id) entry_count,(SELECT COUNT(*) FROM timetable_plan_conflicts c WHERE c.tenant_id=p.tenant_id AND c.plan_id=p.id AND c.resolved_at IS NULL AND c.severity='error') error_count FROM timetable_plan_versions p WHERE p.tenant_id=? ORDER BY p.created_at DESC`).bind(tenantId).all<Record<string,unknown>>()).results??[];}
export async function saveTimetablePlan(env:Env,auth:CoreAuthContext,tenantId:string,input:Record<string,unknown>){requireManage(auth);const planId=optional(input.id,120)||id('tpl_'),starts=day(input.starts_on),ends=day(input.ends_on);if(!starts||!ends||starts>ends)throw new Error('PLAN_PERIOD_INVALID');const status=oneOf(input.status,PLAN_STATUS,'draft'),ts=nowIso(),found=await exists(env,'SELECT 1 FROM timetable_plan_versions WHERE tenant_id=? AND id=?',tenantId,planId);if(found)await env.DB.prepare("UPDATE timetable_plan_versions SET name=?,starts_on=?,ends_on=?,status=CASE WHEN status='published' THEN status ELSE ? END,notes=?,updated_at=? WHERE tenant_id=? AND id=?").bind(required(input.name,300),starts,ends,status,optional(input.notes,5000),ts,tenantId,planId).run();else await env.DB.prepare("INSERT INTO timetable_plan_versions(id,tenant_id,name,starts_on,ends_on,status,notes,published_at,published_by,created_by,created_at,updated_at) VALUES(?,?,?,?,?,? ,?,NULL,NULL,?,?,?)").bind(planId,tenantId,required(input.name,300),starts,ends,status,optional(input.notes,5000),auth.userId,ts,ts).run();await audit(env.DB,auth.userId,'education.timetable_plan_saved',tenantId,undefined,'timetable_plan',planId,{status,starts,ends});return{plan_id:planId};}

export async function getTimetablePlan(env:Env,auth:CoreAuthContext,tenantId:string,planId:string){requireManage(auth);const plan=await env.DB.prepare('SELECT * FROM timetable_plan_versions WHERE tenant_id=? AND id=?').bind(tenantId,planId).first<Record<string,unknown>>();if(!plan)throw new Error('TIMETABLE_PLAN_NOT_FOUND');const [entries,conflicts]=await Promise.all([env.DB.prepare(`SELECT e.*,c.name course_name,s.name subject_name,t.name teacher_name FROM timetable_plan_entries e JOIN courses c ON c.id=e.course_id AND c.tenant_id=e.tenant_id LEFT JOIN subjects s ON s.id=e.subject_id LEFT JOIN teachers t ON t.id=e.teacher_id WHERE e.tenant_id=? AND e.plan_id=? ORDER BY e.starts_at,c.name`).bind(tenantId,planId).all<Record<string,unknown>>(),env.DB.prepare('SELECT * FROM timetable_plan_conflicts WHERE tenant_id=? AND plan_id=? AND resolved_at IS NULL ORDER BY severity DESC,detected_at DESC').bind(tenantId,planId).all<Record<string,unknown>>()]);return{plan,entries:entries.results??[],conflicts:conflicts.results??[]};}

export async function saveTimetablePlanEntry(env:Env,auth:CoreAuthContext,tenantId:string,planId:string,input:Record<string,unknown>){requireManage(auth);const plan=await env.DB.prepare('SELECT status FROM timetable_plan_versions WHERE tenant_id=? AND id=?').bind(tenantId,planId).first<{status:string}>();if(!plan)throw new Error('TIMETABLE_PLAN_NOT_FOUND');if(plan.status==='published'||plan.status==='archived')throw new Error('TIMETABLE_PLAN_LOCKED');const courseId=required(input.course_id,120);courseScope(auth,courseId);const starts=iso(input.starts_at),ends=iso(input.ends_at);if(!starts||!ends||starts>=ends)throw new Error('PLAN_ENTRY_TIME_INVALID');const entryId=optional(input.id,120)||id('tpe_'),type=oneOf(input.activity_type,ACTIVITY_TYPES,'classroom'),supervision=oneOf(input.supervision_mode,SUPERVISION,type.startsWith('self_study')?'self_directed':'instructor'),ts=nowIso(),found=await exists(env,'SELECT 1 FROM timetable_plan_entries WHERE tenant_id=? AND id=? AND plan_id=?',tenantId,entryId,planId);const common=[courseId,optional(input.subject_id,120),optional(input.subject_text,300),optional(input.teacher_id,120),optional(input.teacher_text,300),starts,ends,optional(input.room,300),type,optional(input.location_label,500),supervision,bool(input.attendance_expected??!type.startsWith('self_study')),optional(input.task_text,8000),optional(input.notes,5000),oneOf(input.source,['manual','copy','import','template','automation'] as const,'manual'),optional(input.recurrence_group,120),ts,tenantId,entryId,planId];if(found)await env.DB.prepare('UPDATE timetable_plan_entries SET course_id=?,subject_id=?,subject_text=?,teacher_id=?,teacher_text=?,starts_at=?,ends_at=?,room=?,activity_type=?,location_label=?,supervision_mode=?,attendance_expected=?,task_text=?,notes=?,source=?,recurrence_group=?,updated_at=? WHERE tenant_id=? AND id=? AND plan_id=?').bind(...common).run();else await env.DB.prepare('INSERT INTO timetable_plan_entries(id,tenant_id,plan_id,course_id,subject_id,subject_text,teacher_id,teacher_text,starts_at,ends_at,room,activity_type,location_label,supervision_mode,attendance_expected,task_text,notes,source,recurrence_group,published_lesson_id,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NULL,?,?,?)').bind(entryId,tenantId,planId,courseId,optional(input.subject_id,120),optional(input.subject_text,300),optional(input.teacher_id,120),optional(input.teacher_text,300),starts,ends,optional(input.room,300),type,optional(input.location_label,500),supervision,bool(input.attendance_expected??!type.startsWith('self_study')),optional(input.task_text,8000),optional(input.notes,5000),oneOf(input.source,['manual','copy','import','template','automation'] as const,'manual'),optional(input.recurrence_group,120),auth.userId,ts,ts).run();await audit(env.DB,auth.userId,'education.timetable_plan_entry_saved',tenantId,courseId,'timetable_plan_entry',entryId,{planId,type});return{entry_id:entryId};}

export async function generateTimetablePlanEntries(env:Env,auth:CoreAuthContext,tenantId:string,planId:string,input:Record<string,unknown>){requireManage(auth);const plan=await env.DB.prepare('SELECT starts_on,ends_on,status FROM timetable_plan_versions WHERE tenant_id=? AND id=?').bind(tenantId,planId).first<{starts_on:string;ends_on:string;status:string}>();if(!plan)throw new Error('TIMETABLE_PLAN_NOT_FOUND');if(plan.status==='published'||plan.status==='archived')throw new Error('TIMETABLE_PLAN_LOCKED');const courseId=required(input.course_id,120);courseScope(auth,courseId);const from=day(input.starts_on)||plan.starts_on,to=day(input.ends_on)||plan.ends_on,start=safeString(input.start_time,5),end=safeString(input.end_time,5);if(!start||!end||!/^\d\d:\d\d$/.test(start)||!/^\d\d:\d\d$/.test(end)||end<=start)throw new Error('PLAN_TIME_INVALID');const weekdays=new Set((Array.isArray(input.weekdays)?input.weekdays:[1,2,3,4,5]).map(Number).filter(x=>x>=1&&x<=7)),excluded=new Set((Array.isArray(input.excluded_dates)?input.excluded_dates:[]).map(String)),group=id('rec_');let d=new Date(`${from}T00:00:00Z`),last=new Date(`${to}T00:00:00Z`),count=0;while(d<=last){const dow=d.getUTCDay()===0?7:d.getUTCDay(),date=d.toISOString().slice(0,10);if(weekdays.has(dow)&&!excluded.has(date)){await saveTimetablePlanEntry(env,auth,tenantId,planId,{...input,id:undefined,starts_at:`${date}T${start}:00`,ends_at:`${date}T${end}:00`,recurrence_group:group,source:'automation'});count++;if(count>500)throw new Error('PLAN_GENERATION_TOO_MANY');}d.setUTCDate(d.getUTCDate()+1);}return{generated:count,recurrence_group:group};}

// Ein Stapel zaehlt bei der Plattform als eine einzige Unteranfrage, egal wie viele Anweisungen er
// traegt. Die Obergrenze haelt die einzelne Anfrage klein genug.
const STAPEL_MAX=100;
export async function stapelSchreiben(env:Env,anweisungen:any[]){for(let i=0;i<anweisungen.length;i+=STAPEL_MAX)await env.DB.batch(anweisungen.slice(i,i+STAPEL_MAX));}
// Alle Kalendertage, die ein Zeitraum beruehrt. Damit landen Termine und veroeffentlichter
// Unterricht in Tagesfaechern und die Ueberschneidungspruefung muss nicht jeden mit jedem
// vergleichen. Ueberschneiden sich zwei Zeitraeume, teilen sie zwingend mindestens einen Tag.
function beruehrteTage(start:string,ende:string){const a=String(start).slice(0,10),b=(String(ende)>String(start)?String(ende):String(start)).slice(0,10),out=[a];let d=Date.parse(`${a}T00:00:00.000Z`);if(!Number.isFinite(d))return out;for(let i=0;i<400&&out[out.length-1]<b;i++){d+=86400000;out.push(new Date(d).toISOString().slice(0,10));}return out;}
export function inFaecher<T>(fach:Map<string,T[]>,start:string,ende:string,wert:T){for(const t of beruehrteTage(start,ende)){const l=fach.get(t);if(l)l.push(wert);else fach.set(t,[wert]);}}
export function ausFaechern<T>(fach:Map<string,T[]>,start:string,ende:string){const out:T[]=[],gesehen=new Set<T>();for(const t of beruehrteTage(start,ende))for(const x of fach.get(t)??[]){if(gesehen.has(x))continue;gesehen.add(x);out.push(x);}return out;}

// Ein Jahresplan hat schnell mehrere hundert Termine. Wuerde je Termin einzeln nach Kurs und
// veroeffentlichtem Unterricht gefragt und jeder Konflikt einzeln geschrieben, waere die
// Unteranfragen-Grenze der Plattform lange vor dem Ende des Plans erreicht - der Kunde koennte
// einen Jahresplan anlegen, aber nie pruefen und nie veroeffentlichen. Darum wird alles einmal
// geladen, im Speicher zugeordnet und gestapelt geschrieben: die Zahl der Abfragen haengt nicht
// mehr an der Zahl der Termine.
export async function validateTimetablePlan(env:Env,auth:CoreAuthContext,tenantId:string,planId:string){
  requireManage(auth);
  const data=await getTimetablePlan(env,auth,tenantId,planId),entries=data.entries as any[],ts=nowIso();
  await env.DB.prepare('DELETE FROM timetable_plan_conflicts WHERE tenant_id=? AND plan_id=?').bind(tenantId,planId).run();
  const issues:Array<{entry:any;other?:any;type:string;severity:'info'|'warning'|'error';message:string}>=[];
  const kurse=new Map<string,{start_date:string|null;end_date:string|null}>(),stundenFach=new Map<string,Record<string,unknown>[]>(),terminFach=new Map<string,any[]>();
  if(entries.length){
    let von=String(entries[0].starts_at),bis=String(entries[0].ends_at);
    for(const e of entries){if(String(e.starts_at)<von)von=String(e.starts_at);if(String(e.ends_at)>bis)bis=String(e.ends_at);inFaecher(terminFach,String(e.starts_at),String(e.ends_at),e);}
    const [kursZeilen,stundenZeilen]=await Promise.all([
      env.DB.prepare('SELECT id,start_date,end_date FROM courses WHERE tenant_id=?').bind(tenantId).all<Record<string,unknown>>(),
      env.DB.prepare('SELECT l.id,l.course_id,l.teacher_id,l.room,l.starts_at,l.ends_at FROM lessons l WHERE l.tenant_id=? AND l.starts_at<? AND l.ends_at>?').bind(tenantId,bis,von).all<Record<string,unknown>>(),
    ]);
    for(const c of kursZeilen.results??[])kurse.set(String(c.id),{start_date:(c.start_date??null) as string|null,end_date:(c.end_date??null) as string|null});
    for(const l of stundenZeilen.results??[])inFaecher(stundenFach,String(l.starts_at),String(l.ends_at),l);
  }
  for(const e of entries){
    const type=String(e.activity_type);
    if(!e.subject_id&&!e.subject_text)issues.push({entry:e,type:'missing_subject',severity:'warning',message:'Fach/Lerngebiet fehlt.'});
    if(!type.startsWith('self_study')&&!e.teacher_id&&!e.teacher_text&&type!=='excursion')issues.push({entry:e,type:'missing_teacher',severity:'warning',message:'Dozent/in fehlt.'});
    const course=kurse.get(String(e.course_id)),date=String(e.starts_at).slice(0,10);
    if(course?.start_date&&date<course.start_date||course?.end_date&&date>course.end_date)issues.push({entry:e,type:'outside_course_period',severity:'warning',message:'Eintrag liegt außerhalb des Kurszeitraums.'});
    for(const o of ausFaechern(terminFach,String(e.starts_at),String(e.ends_at))){if(String(o.id)<=String(e.id)||!overlap(String(e.starts_at),String(e.ends_at),String(o.starts_at),String(o.ends_at)))continue;if(e.course_id===o.course_id)issues.push({entry:e,other:o,type:'course_overlap',severity:'error',message:'Klasse/Kurs ist gleichzeitig doppelt verplant.'});if(e.teacher_id&&o.teacher_id&&e.teacher_id===o.teacher_id)issues.push({entry:e,other:o,type:'teacher_overlap',severity:'error',message:'Dozent/in ist gleichzeitig doppelt verplant.'});if(e.room&&o.room&&String(e.room).toLowerCase()===String(o.room).toLowerCase())issues.push({entry:e,other:o,type:'room_overlap',severity:'error',message:'Raum ist gleichzeitig doppelt verplant.'});}
    for(const o of ausFaechern(stundenFach,String(e.starts_at),String(e.ends_at))){if(!overlap(String(e.starts_at),String(e.ends_at),String(o.starts_at),String(o.ends_at)))continue;if(e.published_lesson_id&&String(e.published_lesson_id)===String(o.id))continue;if(e.course_id===o.course_id)issues.push({entry:e,type:'course_overlap',severity:'error',message:'Kollidiert mit bereits veröffentlichtem Unterricht dieser Klasse.'});if(e.teacher_id&&o.teacher_id&&e.teacher_id===o.teacher_id)issues.push({entry:e,type:'teacher_overlap',severity:'error',message:'Kollidiert mit bereits veröffentlichtem Termin des Dozenten.'});if(e.room&&o.room&&String(e.room).toLowerCase()===String(o.room).toLowerCase())issues.push({entry:e,type:'room_overlap',severity:'error',message:'Kollidiert mit bereits veröffentlichtem Raumtermin.'});}
  }
  await stapelSchreiben(env,issues.map(x=>env.DB.prepare('INSERT INTO timetable_plan_conflicts(id,tenant_id,plan_id,entry_id,conflicting_entry_id,conflict_type,severity,message,detected_at,resolved_at) VALUES(?,?,?,?,?,?,?,?,?,NULL)').bind(id('tpc_'),tenantId,planId,x.entry.id,x.other?.id||null,x.type,x.severity,x.message,ts)));
  await audit(env.DB,auth.userId,'education.timetable_plan_validated',tenantId,undefined,'timetable_plan',planId,{issues:issues.length,errors:issues.filter(x=>x.severity==='error').length});
  return{issues,errors:issues.filter(x=>x.severity==='error').length,warnings:issues.filter(x=>x.severity==='warning').length};
}

// Faecher und Dozenten werden einmal geladen statt je Termin abgefragt. Neu entstehende kommen
// sofort in dieselbe Zuordnung, damit zwei Termine mit demselben Freitext nicht zwei
// Stammdatensaetze erzeugen. Der Namensvergleich in Kleinschreibung erfasst dabei auch Umlaute,
// die ein reiner ASCII-Vergleich als verschiedene Namen behandeln wuerde.
type Stammdaten={proId:Set<string>;proName:Map<string,string>;neu:any[]};
function stammLaden(zeilen:Array<Record<string,unknown>>):Stammdaten{const s:Stammdaten={proId:new Set(),proName:new Map(),neu:[]};for(const r of zeilen){const rid=String(r.id),name=String(r.name??'').toLowerCase();s.proId.add(rid);if(name&&!s.proName.has(name))s.proName.set(name,rid);}return s;}
function stammAufloesen(env:Env,tenantId:string,art:'subject'|'teacher',s:Stammdaten,idValue:unknown,textValue:unknown){
  const vorhanden=optional(idValue,120);
  if(vorhanden&&s.proId.has(vorhanden))return vorhanden;
  const name=optional(textValue,300);
  if(!name)return null;
  const treffer=s.proName.get(name.toLowerCase());
  if(treffer)return treffer;
  const neueId=id(art==='subject'?'sub_':'tch_');
  s.proId.add(neueId);s.proName.set(name.toLowerCase(),neueId);
  s.neu.push(art==='subject'
    ?env.DB.prepare('INSERT INTO subjects(id,tenant_id,name,short_name,created_at) VALUES(?,?,?,?,?)').bind(neueId,tenantId,name,null,nowIso())
    :env.DB.prepare('INSERT INTO teachers(id,tenant_id,name,email,created_at) VALUES(?,?,?,?,?)').bind(neueId,tenantId,name,null,nowIso()));
  return neueId;
}
// Veroeffentlichen schrieb frueher je Termin einzeln (Stammdaten pruefen, Unterricht anlegen,
// Eintrag verknuepfen, Lernform festhalten). Ein Jahresplan haette damit die Unteranfragen-Grenze
// der Plattform gerissen und waere mitten im Schreiben stehengeblieben - der schlimmste Fall:
// halb veroeffentlichter Unterricht. Jetzt entsteht alles gestapelt.
export async function publishTimetablePlan(env:Env,auth:CoreAuthContext,tenantId:string,planId:string){
  requireManage(auth);
  const validation=await validateTimetablePlan(env,auth,tenantId,planId);
  if(validation.errors)throw new Error('TIMETABLE_PLAN_HAS_CONFLICTS');
  const data=await getTimetablePlan(env,auth,tenantId,planId),plan=data.plan as any;
  if(plan.status==='published')return{published:0,already_published:true};
  if(plan.status==='archived')throw new Error('TIMETABLE_PLAN_LOCKED');
  const offen=(data.entries as any[]).filter(e=>!e.published_lesson_id),ts=nowIso();
  const [fachZeilen,dozentZeilen]=await Promise.all([
    env.DB.prepare('SELECT id,name FROM subjects WHERE tenant_id=?').bind(tenantId).all<Record<string,unknown>>(),
    env.DB.prepare('SELECT id,name FROM teachers WHERE tenant_id=?').bind(tenantId).all<Record<string,unknown>>(),
  ]);
  const faecher=stammLaden(fachZeilen.results??[]),dozenten=stammLaden(dozentZeilen.results??[]),anweisungen:any[]=[];
  let count=0;
  for(const e of offen){
    const subjectId=stammAufloesen(env,tenantId,'subject',faecher,e.subject_id,e.subject_text),teacherId=stammAufloesen(env,tenantId,'teacher',dozenten,e.teacher_id,e.teacher_text),lessonId=id('les_');
    anweisungen.push(env.DB.prepare('INSERT INTO lessons(id,tenant_id,course_id,subject_id,teacher_id,starts_at,ends_at,room,notes,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(lessonId,tenantId,e.course_id,subjectId,teacherId,e.starts_at,e.ends_at,e.room,[e.notes,e.task_text&&`Auftrag: ${e.task_text}`,e.activity_type!=='classroom'?`Lernform: ${e.activity_type}`:null].filter(Boolean).join('\n')||null,ts));
    anweisungen.push(env.DB.prepare('UPDATE timetable_plan_entries SET published_lesson_id=?,updated_at=? WHERE tenant_id=? AND id=?').bind(lessonId,ts,tenantId,e.id));
    anweisungen.push(env.DB.prepare('INSERT INTO instruction_activity_details(id,tenant_id,course_id,lesson_id,session_id,activity_type,location_label,supervision_mode,attendance_expected,evidence_required,task_text,expected_outcome,safety_notes,external_contact,created_by,created_at,updated_at) VALUES(?,?,?,?,NULL,?,?,?,?,0,?,?,NULL,NULL,?,?,?)').bind(id('act_'),tenantId,e.course_id,lessonId,e.activity_type,e.location_label,e.supervision_mode,e.attendance_expected,e.task_text,null,auth.userId,ts,ts));
    if(e.activity_type==='excursion')anweisungen.push(env.DB.prepare("INSERT INTO excursion_events(id,tenant_id,course_id,lesson_id,title,destination,meeting_point,starts_at,ends_at,responsible_teacher_id,external_contact,transport,learning_objective,safety_notes,consent_required,status,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,NULL,NULL,?,NULL,0,'planned',?,?,?)").bind(id('exc_'),tenantId,e.course_id,lessonId,e.subject_text||e.subject_name||'Exkursion',e.location_label||e.room||'Exkursion',e.room||null,e.starts_at,e.ends_at,teacherId,e.task_text||null,auth.userId,ts,ts));
    count++;
  }
  // Stammdaten zuerst: der neue Unterricht verweist auf sie.
  await stapelSchreiben(env,[...faecher.neu,...dozenten.neu]);
  await stapelSchreiben(env,anweisungen);
  await env.DB.prepare("UPDATE timetable_plan_versions SET status='published',published_at=?,published_by=?,updated_at=? WHERE tenant_id=? AND id=?").bind(ts,auth.userId,ts,tenantId,planId).run();
  await audit(env.DB,auth.userId,'education.timetable_plan_published',tenantId,undefined,'timetable_plan',planId,{published:count});
  return{published:count};
}

async function signatureSnapshot(env:Env,tenantId:string,documentId:string){const document=await env.DB.prepare('SELECT * FROM signature_documents WHERE tenant_id=? AND id=?').bind(tenantId,documentId).first<Record<string,unknown>>();if(!document)throw new Error('SIGNATURE_DOCUMENT_NOT_FOUND');return document;}
export async function createSignatureDocument(env:Env,auth:CoreAuthContext,tenantId:string,input:Record<string,unknown>){requireContent(auth);const courseId=optional(input.course_id,120);if(courseId)courseScope(auth,courseId);const snapshot=typeof input.snapshot==='string'?String(input.snapshot):JSON.stringify(input.snapshot??{}),hash=await sha256Text(snapshot),documentId=id('sigdoc_'),ts=nowIso(),type=oneOf(input.document_type,['report_book','excursion_consent','classbook_evidence','practice_evidence','certificate_acknowledgement','custom'] as const,'custom'),level=oneOf(input.signature_level,['platform_authenticated','external_advanced','external_qualified'] as const,'platform_authenticated');await env.DB.prepare("INSERT INTO signature_documents(id,tenant_id,course_id,document_type,entity_type,entity_id,title,snapshot_json,snapshot_sha256,signature_level,status,created_by,created_at,completed_at) VALUES(?,?,?,?,?,?,?,?,?,?,'open',?,?,NULL)").bind(documentId,tenantId,courseId,type,required(input.entity_type,120),required(input.entity_id,160),required(input.title,400),snapshot,hash,level,auth.userId,ts).run();const requests=Array.isArray(input.signers)?input.signers:[];for(let i=0;i<requests.length;i++){const r=(requests[i]&&typeof requests[i]==='object'?requests[i]:{}) as Record<string,unknown>;await env.DB.prepare("INSERT INTO signature_requests(id,tenant_id,document_id,signer_user_id,signer_role,signing_order,status,due_at,reminder_after,signed_at,created_at,updated_at) VALUES(?,?,?,?,?,?,'pending',?,?,NULL,?,?)").bind(id('sigreq_'),tenantId,documentId,optional(r.user_id,120),required(r.role,120),Number(r.order??i),iso(r.due_at),iso(r.reminder_after),ts,ts).run();}await audit(env.DB,auth.userId,'education.signature_document_created',tenantId,courseId||undefined,'signature_document',documentId,{type,level,signers:requests.length});return{document_id:documentId,sha256:hash};}

export async function listMySignatureRequests(env:Env,auth:CoreAuthContext,tenantId:string){return(await env.DB.prepare(`SELECT r.*,d.course_id,d.document_type,d.entity_type,d.entity_id,d.title,d.snapshot_sha256,d.signature_level,d.status document_status FROM signature_requests r JOIN signature_documents d ON d.id=r.document_id AND d.tenant_id=r.tenant_id WHERE r.tenant_id=? AND (r.signer_user_id=? OR r.signer_user_id IS NULL AND r.signer_role IN ('teacher','tenant_admin')) AND r.status='pending' ORDER BY COALESCE(r.due_at,'9999'),r.signing_order`).bind(tenantId,auth.userId).all<Record<string,unknown>>()).results??[];}
export async function signDocument(env:Env,auth:CoreAuthContext,tenantId:string,requestId:string,input:Record<string,unknown>){const req=await env.DB.prepare(`SELECT r.*,d.course_id,d.snapshot_sha256,d.signature_level,d.status document_status FROM signature_requests r JOIN signature_documents d ON d.id=r.document_id AND d.tenant_id=r.tenant_id WHERE r.tenant_id=? AND r.id=?`).bind(tenantId,requestId).first<Record<string,unknown>>();if(!req)throw new Error('SIGNATURE_REQUEST_NOT_FOUND');if(req.status!=='pending'||req.document_status==='cancelled'||req.document_status==='superseded')throw new Error('SIGNATURE_REQUEST_CLOSED');if(req.signer_user_id&&String(req.signer_user_id)!==auth.userId&&!isAdmin(auth))throw new Error('FORBIDDEN_SIGNATURE_REQUEST');if(!req.signer_user_id){if(String(req.signer_role)==='teacher'){if(!req.course_id)throw new Error('SIGNATURE_COURSE_REQUIRED');await teacherAttendanceAuth(env,auth,tenantId,String(req.course_id));}else if(String(req.signer_role)==='tenant_admin'&&!isAdmin(auth))throw new Error('TENANT_ADMIN_REQUIRED');}
  if(input.confirm!==true)throw new Error('SIGNATURE_CONFIRMATION_REQUIRED');const typed=required(input.typed_name,240),display=auth.session?.displayName||typed;if(typed.toLocaleLowerCase('de-DE')!==String(display).trim().toLocaleLowerCase('de-DE')&&!isAdmin(auth))throw new Error('SIGNATURE_NAME_MISMATCH');const method=oneOf(req.signature_level,['platform_authenticated','external_advanced','external_qualified'] as const,'platform_authenticated');if(method!=='platform_authenticated'&&!input.provider_reference)throw new Error('EXTERNAL_SIGNATURE_REFERENCE_REQUIRED');const ts=nowIso(),signatureId=id('sig_'),authMethod=auth.session?.authMethod||'password',federatedAuth=authMethod==='oidc'?1:0;await env.DB.prepare('INSERT INTO digital_signatures(id,tenant_id,document_id,request_id,signer_user_id,signer_display_name,signer_role,method,document_sha256,declaration_text,signed_at,auth_method,federated_auth,provider,provider_reference) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(signatureId,tenantId,String(req.document_id),requestId,auth.userId,display,String(req.signer_role),method,String(req.snapshot_sha256),required(input.declaration_text,1000),ts,authMethod,federatedAuth,optional(input.provider,120),optional(input.provider_reference,500)).run();await env.DB.prepare("UPDATE signature_requests SET status='signed',signer_user_id=COALESCE(signer_user_id,?),signed_at=?,updated_at=? WHERE tenant_id=? AND id=?").bind(auth.userId,ts,ts,tenantId,requestId).run();const pending=await env.DB.prepare("SELECT COUNT(*) n FROM signature_requests WHERE tenant_id=? AND document_id=? AND status='pending'").bind(tenantId,String(req.document_id)).first<{n:number}>();await env.DB.prepare(`UPDATE signature_documents SET status=?,completed_at=? WHERE tenant_id=? AND id=?`).bind(Number(pending?.n||0)?'partially_signed':'complete',Number(pending?.n||0)?null:ts,tenantId,String(req.document_id)).run();await audit(env.DB,auth.userId,'education.document_signed',tenantId,req.course_id?String(req.course_id):undefined,'signature_document',String(req.document_id),{method,federatedAuth:!!federatedAuth});return{signature_id:signatureId,complete:Number(pending?.n||0)===0};}

export async function listMyReportBooks(env:Env,auth:CoreAuthContext,tenantId:string,courseId:string){courseScope(auth,courseId);if(!['participant','class_admin','tenant_admin','platform_admin'].includes(auth.role))throw new Error('FORBIDDEN_REPORT_BOOK');const uid=isAdmin(auth)&&optional((auth as any).participant_user_id,120)?String((auth as any).participant_user_id):auth.userId;const periods=(await env.DB.prepare('SELECT * FROM report_book_periods WHERE tenant_id=? AND course_id=? AND participant_user_id=? ORDER BY period_start DESC').bind(tenantId,courseId,uid).all<Record<string,unknown>>()).results??[];for(const p of periods)(p as any).entries=(await env.DB.prepare('SELECT * FROM report_book_entries WHERE tenant_id=? AND period_id=? ORDER BY entry_date,id').bind(tenantId,p.id).all<Record<string,unknown>>()).results??[];return periods;}
export async function ensureReportBookPeriod(env:Env,auth:CoreAuthContext,tenantId:string,courseId:string,input:Record<string,unknown>){courseScope(auth,courseId);if(!['participant','class_admin'].includes(auth.role)&&!isAdmin(auth))throw new Error('FORBIDDEN_REPORT_BOOK');const start=day(input.period_start),end=day(input.period_end);if(!start||!end||start>end)throw new Error('REPORT_BOOK_PERIOD_INVALID');const uid=auth.userId,existing=await env.DB.prepare('SELECT id FROM report_book_periods WHERE tenant_id=? AND course_id=? AND participant_user_id=? AND period_start=? AND period_end=?').bind(tenantId,courseId,uid,start,end).first<{id:string}>();if(existing)return{period_id:existing.id};const periodId=id('rbp_'),ts=nowIso();await env.DB.prepare("INSERT INTO report_book_periods(id,tenant_id,course_id,participant_user_id,period_start,period_end,title,status,total_minutes,submitted_at,reviewed_by,reviewed_at,review_note,signature_document_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'draft',0,NULL,NULL,NULL,NULL,NULL,?,?)").bind(periodId,tenantId,courseId,uid,start,end,optional(input.title,300),ts,ts).run();return{period_id:periodId};}
// Berichtshefte fuer eine ganze Klasse eroeffnen. Der Traeger legt den Zeitraum an - schreiben
// und einreichen bleibt Sache der Teilnehmenden, sonst waere der Nachweis keiner mehr. Deshalb
// entstehen hier ausschliesslich leere Zeitraeume, niemals Eintraege.
// Gemessen kostet ein eroeffneter Zeitraum rund 2 Abfragen. 300 Personen bleiben damit sicher
// unter der Unteranfragen-Grenze der Plattform.
const REPORT_BOOK_BATCH_MAX=300;
export async function openReportBookPeriodsForCourse(env:Env,auth:CoreAuthContext,tenantId:string,courseId:string,input:Record<string,unknown>){
  requireManage(auth);courseScope(auth,courseId);
  const start=day(input.period_start),end=day(input.period_end);
  if(!start||!end||start>end)throw new Error('REPORT_BOOK_PERIOD_INVALID');
  const titel=optional(input.title,300);
  const teilnehmende=(await env.DB.prepare("SELECT DISTINCT u.id,u.display_name FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.tenant_id=? AND m.course_id=? AND m.role='participant' AND u.status='active' ORDER BY u.display_name").bind(tenantId,courseId).all<{id:string;display_name:string}>()).results??[];
  if(teilnehmende.length>REPORT_BOOK_BATCH_MAX)throw new Error('REPORT_BOOK_BATCH_TOO_LARGE');
  const zeitraeume:Array<{user_id:string;display_name:string;period_id:string;created:boolean}>=[];
  for(const t of teilnehmende){
    const vorhanden=await env.DB.prepare('SELECT id FROM report_book_periods WHERE tenant_id=? AND course_id=? AND participant_user_id=? AND period_start=? AND period_end=?').bind(tenantId,courseId,t.id,start,end).first<{id:string}>();
    if(vorhanden){zeitraeume.push({user_id:t.id,display_name:t.display_name,period_id:vorhanden.id,created:false});continue;}
    const periodId=id('rbp_'),ts=nowIso();
    await env.DB.prepare("INSERT INTO report_book_periods(id,tenant_id,course_id,participant_user_id,period_start,period_end,title,status,total_minutes,submitted_at,reviewed_by,reviewed_at,review_note,signature_document_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'draft',0,NULL,NULL,NULL,NULL,NULL,?,?)").bind(periodId,tenantId,courseId,t.id,start,end,titel,ts,ts).run();
    zeitraeume.push({user_id:t.id,display_name:t.display_name,period_id:periodId,created:true});
  }
  await audit(env.DB,auth.userId,'education.report_book_periods_opened',tenantId,courseId,'course',courseId,{start,end,participants:teilnehmende.length,created:zeitraeume.filter(x=>x.created).length});
  return{course_id:courseId,period_start:start,period_end:end,participants:teilnehmende.length,
    created:zeitraeume.filter(x=>x.created).length,existing:zeitraeume.filter(x=>!x.created).length,periods:zeitraeume,entries_created:0};
}

// Wer ist noch nicht so weit? Die Uebersicht des Traegers zeigt jeden Teilnehmenden - auch die
// ohne Zeitraum und die, die noch im Entwurf stecken. Sie zeigt Stand und Umfang, nicht Inhalte.
export async function reportBookCoverageForCourse(env:Env,auth:CoreAuthContext,tenantId:string,courseId:string,input:Record<string,unknown>={}){
  requireManage(auth);courseScope(auth,courseId);
  const start=day(input.period_start),end=day(input.period_end);
  const zeilen=(await env.DB.prepare(`SELECT u.id user_id,u.display_name,p.id period_id,p.status,p.total_minutes,p.submitted_at,p.reviewed_at,
      (SELECT COUNT(*) FROM report_book_entries e WHERE e.tenant_id=p.tenant_id AND e.period_id=p.id) entry_count
    FROM memberships m JOIN users u ON u.id=m.user_id
    LEFT JOIN report_book_periods p ON p.tenant_id=m.tenant_id AND p.course_id=m.course_id AND p.participant_user_id=u.id
      AND (?1 IS NULL OR p.period_start=?1) AND (?2 IS NULL OR p.period_end=?2)
    WHERE m.tenant_id=?3 AND m.course_id=?4 AND m.role='participant' AND u.status='active'
    ORDER BY u.display_name`).bind(start,end,tenantId,courseId).all<Record<string,unknown>>()).results??[];
  const stand=(r:Record<string,unknown>)=>r.period_id?String(r.status||'draft'):'missing';
  return{course_id:courseId,participants:zeilen.length,
    rows:zeilen.map(r=>({user_id:String(r.user_id),display_name:String(r.display_name||''),period_id:r.period_id?String(r.period_id):null,
      state:stand(r),entry_count:Number(r.entry_count||0),total_minutes:Number(r.total_minutes||0),
      submitted_at:r.submitted_at?String(r.submitted_at):null,reviewed_at:r.reviewed_at?String(r.reviewed_at):null})),
    open:zeilen.filter(r=>!r.period_id||['draft','revision_required'].includes(String(r.status))).length};
}

export async function saveReportBookEntry(env:Env,auth:CoreAuthContext,tenantId:string,courseId:string,periodId:string,input:Record<string,unknown>){courseScope(auth,courseId);const p=await env.DB.prepare('SELECT participant_user_id,status FROM report_book_periods WHERE tenant_id=? AND course_id=? AND id=?').bind(tenantId,courseId,periodId).first<{participant_user_id:string;status:string}>();if(!p)throw new Error('REPORT_BOOK_PERIOD_NOT_FOUND');if(p.participant_user_id!==auth.userId&&!isAdmin(auth))throw new Error('FORBIDDEN_REPORT_BOOK');if(!['draft','revision_required'].includes(p.status))throw new Error('REPORT_BOOK_LOCKED');const entryId=optional(input.id,120)||id('rbe_'),date=day(input.entry_date);if(!date)throw new Error('REPORT_BOOK_DATE_REQUIRED');const type=oneOf(input.activity_type,ACTIVITY_TYPES,'classroom'),minutes=Math.max(0,Math.min(1440,Number(input.minutes||0)||0)),ts=nowIso(),found=await exists(env,'SELECT 1 FROM report_book_entries WHERE tenant_id=? AND period_id=? AND id=?',tenantId,periodId,entryId);if(found)await env.DB.prepare('UPDATE report_book_entries SET entry_date=?,activity_type=?,location_label=?,subject_text=?,minutes=?,activity_text=?,learning_outcome=?,source_type=?,source_id=?,updated_at=? WHERE tenant_id=? AND period_id=? AND id=?').bind(date,type,optional(input.location_label,500),optional(input.subject_text,300),minutes,required(input.activity_text,8000),optional(input.learning_outcome,6000),oneOf(input.source_type,['manual','lesson','self_study','practice','excursion','legacy_import'] as const,'manual'),optional(input.source_id,160),ts,tenantId,periodId,entryId).run();else await env.DB.prepare('INSERT INTO report_book_entries(id,tenant_id,period_id,entry_date,activity_type,location_label,subject_text,minutes,activity_text,learning_outcome,source_type,source_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(entryId,tenantId,periodId,date,type,optional(input.location_label,500),optional(input.subject_text,300),minutes,required(input.activity_text,8000),optional(input.learning_outcome,6000),oneOf(input.source_type,['manual','lesson','self_study','practice','excursion','legacy_import'] as const,'manual'),optional(input.source_id,160),ts,ts).run();await env.DB.prepare('UPDATE report_book_periods SET total_minutes=(SELECT COALESCE(SUM(minutes),0) FROM report_book_entries WHERE tenant_id=? AND period_id=?),updated_at=? WHERE tenant_id=? AND id=?').bind(tenantId,periodId,ts,tenantId,periodId).run();return{entry_id:entryId};}

export async function generateReportBookFromSchedule(env:Env,auth:CoreAuthContext,tenantId:string,courseId:string,periodId:string){courseScope(auth,courseId);const p=await env.DB.prepare('SELECT participant_user_id,period_start,period_end,status FROM report_book_periods WHERE tenant_id=? AND course_id=? AND id=?').bind(tenantId,courseId,periodId).first<{participant_user_id:string;period_start:string;period_end:string;status:string}>();if(!p)throw new Error('REPORT_BOOK_PERIOD_NOT_FOUND');if(p.participant_user_id!==auth.userId)throw new Error('FORBIDDEN_REPORT_BOOK');if(!['draft','revision_required'].includes(p.status))throw new Error('REPORT_BOOK_LOCKED');const rows=(await env.DB.prepare(`SELECT l.id,l.starts_at,l.ends_at,l.room,s.name subject,t.name teacher,a.activity_type,a.location_label,a.task_text,a.expected_outcome,cb.topic,cb.content_summary
    FROM lessons l LEFT JOIN subjects s ON s.id=l.subject_id LEFT JOIN teachers t ON t.id=l.teacher_id LEFT JOIN instruction_activity_details a ON a.tenant_id=l.tenant_id AND a.lesson_id=l.id LEFT JOIN attendance_sessions ses ON ses.tenant_id=l.tenant_id AND ses.course_id=l.course_id AND ses.source_ref=l.id LEFT JOIN classbook_entries cb ON cb.session_id=ses.id
    WHERE l.tenant_id=? AND l.course_id=? AND substr(l.starts_at,1,10) BETWEEN ? AND ? ORDER BY l.starts_at`).bind(tenantId,courseId,p.period_start,p.period_end).all<Record<string,unknown>>()).results??[];let created=0;for(const r of rows){if(await exists(env,"SELECT 1 FROM report_book_entries WHERE tenant_id=? AND period_id=? AND source_type='lesson' AND source_id=?",tenantId,periodId,String(r.id)))continue;const start=new Date(String(r.starts_at)),end=new Date(String(r.ends_at)),minutes=Math.max(0,Math.round((end.getTime()-start.getTime())/60000)),type=oneOf(r.activity_type,ACTIVITY_TYPES,'classroom'),activity=String(r.content_summary||r.topic||r.task_text||r.subject||'Unterricht'),ts=nowIso();await env.DB.prepare("INSERT INTO report_book_entries(id,tenant_id,period_id,entry_date,activity_type,location_label,subject_text,minutes,activity_text,learning_outcome,source_type,source_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,'lesson',?,?,?)").bind(id('rbe_'),tenantId,periodId,String(r.starts_at).slice(0,10),type,r.location_label||r.room||null,r.subject||null,minutes,activity,r.expected_outcome||null,String(r.id),ts,ts).run();created++;}const ts=nowIso();await env.DB.prepare('UPDATE report_book_periods SET total_minutes=(SELECT COALESCE(SUM(minutes),0) FROM report_book_entries WHERE tenant_id=? AND period_id=?),updated_at=? WHERE tenant_id=? AND id=?').bind(tenantId,periodId,ts,tenantId,periodId).run();return{generated:created};}

export async function submitReportBook(env:Env,auth:CoreAuthContext,tenantId:string,courseId:string,periodId:string){courseScope(auth,courseId);const p=await env.DB.prepare('SELECT * FROM report_book_periods WHERE tenant_id=? AND course_id=? AND id=?').bind(tenantId,courseId,periodId).first<Record<string,unknown>>();if(!p)throw new Error('REPORT_BOOK_PERIOD_NOT_FOUND');if(String(p.participant_user_id)!==auth.userId)throw new Error('FORBIDDEN_REPORT_BOOK');if(!['draft','revision_required'].includes(String(p.status)))throw new Error('REPORT_BOOK_LOCKED');const entries=(await env.DB.prepare('SELECT entry_date,activity_type,location_label,subject_text,minutes,activity_text,learning_outcome FROM report_book_entries WHERE tenant_id=? AND period_id=? ORDER BY entry_date,id').bind(tenantId,periodId).all<Record<string,unknown>>()).results??[];if(!entries.length)throw new Error('REPORT_BOOK_EMPTY');const snapshot=JSON.stringify({period:{id:p.id,course_id:p.course_id,participant_user_id:p.participant_user_id,period_start:p.period_start,period_end:p.period_end,title:p.title,total_minutes:p.total_minutes},entries}),hash=await sha256Text(snapshot),documentId=id('sigdoc_'),requestId=id('sigreq_'),teacherRequest=id('sigreq_'),ts=nowIso();await env.DB.prepare("UPDATE signature_documents SET status='superseded' WHERE tenant_id=? AND document_type='report_book' AND entity_type='report_book_period' AND entity_id=? AND status IN ('open','partially_signed')").bind(tenantId,periodId).run();await env.DB.prepare("INSERT INTO signature_documents(id,tenant_id,course_id,document_type,entity_type,entity_id,title,snapshot_json,snapshot_sha256,signature_level,status,created_by,created_at,completed_at) VALUES(?,?,?,'report_book','report_book_period',?,?,?,?, 'platform_authenticated','open',?,?,NULL)").bind(documentId,tenantId,courseId,periodId,String(p.title||`Berichtsheft ${p.period_start}–${p.period_end}`),snapshot,hash,auth.userId,ts).run();await env.DB.batch([env.DB.prepare("INSERT INTO signature_requests(id,tenant_id,document_id,signer_user_id,signer_role,signing_order,status,due_at,reminder_after,signed_at,created_at,updated_at) VALUES(?,?,?,?,'participant',0,'pending',NULL,NULL,NULL,?,?)").bind(requestId,tenantId,documentId,auth.userId,ts,ts),env.DB.prepare("INSERT INTO signature_requests(id,tenant_id,document_id,signer_user_id,signer_role,signing_order,status,due_at,reminder_after,signed_at,created_at,updated_at) VALUES(?,?,?,NULL,'teacher',1,'pending',NULL,NULL,NULL,?,?)").bind(teacherRequest,tenantId,documentId,ts,ts)]);await env.DB.prepare("UPDATE report_book_periods SET status='submitted',submitted_at=?,signature_document_id=?,updated_at=? WHERE tenant_id=? AND id=?").bind(ts,documentId,ts,tenantId,periodId).run();await audit(env.DB,auth.userId,'education.report_book_submitted',tenantId,courseId,'report_book_period',periodId,{sha256:hash});return{document_id:documentId,participant_signature_request_id:requestId};}

export async function teacherReportBooks(env:Env,auth:CoreAuthContext,tenantId:string,courseId:string){await teacherAttendanceAuth(env,auth,tenantId,courseId);return(await env.DB.prepare(`SELECT p.*,u.display_name participant_name,u.email participant_email,d.status signature_status,(SELECT COUNT(*) FROM signature_requests r WHERE r.document_id=d.id AND r.status='pending') pending_signatures FROM report_book_periods p JOIN users u ON u.id=p.participant_user_id LEFT JOIN signature_documents d ON d.id=p.signature_document_id WHERE p.tenant_id=? AND p.course_id=? AND p.status IN ('submitted','revision_required','approved','signed') ORDER BY p.period_end DESC,u.display_name`).bind(tenantId,courseId).all<Record<string,unknown>>()).results??[];}
export async function reviewReportBook(env:Env,auth:CoreAuthContext,tenantId:string,courseId:string,periodId:string,input:Record<string,unknown>){await teacherAttendanceAuth(env,auth,tenantId,courseId);const status=oneOf(input.status,['revision_required','approved'] as const,'approved'),p=await env.DB.prepare('SELECT signature_document_id FROM report_book_periods WHERE tenant_id=? AND course_id=? AND id=?').bind(tenantId,courseId,periodId).first<{signature_document_id:string|null}>();if(!p)throw new Error('REPORT_BOOK_PERIOD_NOT_FOUND');const ts=nowIso();await env.DB.prepare('UPDATE report_book_periods SET status=?,reviewed_by=?,reviewed_at=?,review_note=?,updated_at=? WHERE tenant_id=? AND course_id=? AND id=?').bind(status,auth.userId,ts,optional(input.review_note,5000),ts,tenantId,courseId,periodId).run();if(status==='revision_required'&&p.signature_document_id)await env.DB.prepare("UPDATE signature_documents SET status='superseded' WHERE tenant_id=? AND id=? AND status IN ('open','partially_signed')").bind(tenantId,p.signature_document_id).run();if(status==='approved'&&p.signature_document_id)await env.DB.prepare("UPDATE signature_requests SET signer_user_id=? WHERE tenant_id=? AND document_id=? AND signer_role='teacher' AND signer_user_id IS NULL").bind(auth.userId,tenantId,p.signature_document_id).run();await audit(env.DB,auth.userId,'education.report_book_reviewed',tenantId,courseId,'report_book_period',periodId,{status});return{status,signature_document_id:p.signature_document_id};}

const CLASSBOOK_ALIASES={date:['datum','date','tag','unterrichtstag'],start:['beginn','start','von','uhrzeit'],end:['ende','end','bis','schluss'],subject:['fach','subject','lernfeld','modul'],teacher:['dozent','lehrer','teacher','trainer','referent'],room:['raum','room','ort'],topic:['thema','unterrichtsthema','behandeltes_thema','inhaltsthema'],content:['inhalte','inhalt','content','behandelte_inhalte','unterrichtsinhalt'],homework:['hausaufgaben','homework','nachste_schritte','naechste_schritte'],mode:['unterrichtsart','modus','format','delivery_mode','lernform'],status:['status','abgeschlossen','completed']} as const;
function detect(headers:string[],key:keyof typeof CLASSBOOK_ALIASES){const aliases=CLASSBOOK_ALIASES[key] as readonly string[];return headers.find(h=>aliases.includes(normalizeHeader(h)))||headers.find(h=>aliases.some(a=>normalizeHeader(h).includes(a)))||null;}
async function parseLegacyFile(file:File){const name=file.name.toLowerCase();if(name.endsWith('.csv')||file.type==='text/csv')return parseCsv(await file.text());if(name.endsWith('.xlsx')||file.type==='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')return parseXlsx(await file.arrayBuffer());throw new Error('LEGACY_STRUCTURED_FILE_UNSUPPORTED');}
function normalizeMode(value:unknown):ActivityType{const s=normalizeHeader(String(value||''));if(/selbst.*home|homeoffice|selbstlern.*zuhause/.test(s))return'self_study_home';if(/selbst.*schule|selbstlern.*schule/.test(s))return'self_study_school';if(/selbstlern|selbststudium/.test(s))return'self_study_other';if(/exkursion|ausflug|besichtigung/.test(s))return'excursion';if(/online|remote|teams|webinar/.test(s))return'live_remote';if(/hybrid/.test(s))return'hybrid_live';if(/praxis|praktikum/.test(s))return'practice';if(/projekt/.test(s))return'project';if(/prufung|pruefung|klausur/.test(s))return'exam';return'classroom';}
async function storeLegacyFile(env:Env,tenantId:string,actor:string,file:File,batchId:string){const buffer=await file.arrayBuffer(),hash=await sha256Buffer(buffer),fileId=id('file_'),name=file.name.replace(/[\\/]+/g,'_').slice(0,240),key=`legacy/${tenantId}/${batchId}/${crypto.randomUUID()}-${name}`;await env.FILES.put(key,buffer,{httpMetadata:{contentType:file.type||'application/octet-stream',contentDisposition:`attachment; filename="${name.replace(/"/g,'')}"`},customMetadata:{tenantId,purpose:'legacy_import',batchId}});await env.DB.prepare('INSERT INTO portability_files(id,tenant_id,object_key,original_name,content_type,size_bytes,uploaded_by,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(fileId,tenantId,key,name,file.type||'application/octet-stream',file.size,actor,nowIso()).run();return{fileId,hash};}

export async function previewLegacyImport(env:Env,auth:CoreAuthContext,tenantId:string,request:Request){requireManage(auth);const form=await request.formData(),file=form.get('file');if(!(file instanceof File)||!file.size)throw new Error('LEGACY_FILE_REQUIRED');if(file.size>25*1024*1024)throw new Error('LEGACY_FILE_TOO_LARGE');const resource=oneOf(form.get('resource_type'),['classbook','timetable','curriculum','report_book','attendance_summary','documents','mixed'] as const,'classbook'),mode=oneOf(form.get('mode'),['merge','archive_only','baseline'] as const,'merge'),courseId=optional(form.get('course_id'),120);if(courseId)courseScope(auth,courseId);const batchId=id('leg_'),stored=await storeLegacyFile(env,tenantId,auth.userId,file,batchId),ts=nowIso(),archiveOnly=mode==='archive_only'||!(/\.csv$|\.xlsx$/i.test(file.name));let rowCount=0,warnings=0,errors=0,rows:any[]=[];if(!archiveOnly&&resource==='classbook'){if(!courseId)throw new Error('COURSE_ID_REQUIRED');const parsed=await parseLegacyFile(file),mapping:Record<string,string|null>={};for(const k of Object.keys(CLASSBOOK_ALIASES) as Array<keyof typeof CLASSBOOK_ALIASES>)mapping[k]=detect(parsed.headers,k);let override:Record<string,string>={};try{override=JSON.parse(String(form.get('mapping_json')||'{}'));}catch{}for(const [k,v] of Object.entries(override))if(parsed.headers.includes(v))mapping[k]=v;rows=parsed.rows.map((r:any,index:number)=>{const get=(k:string)=>mapping[k]?r[mapping[k] as string]:undefined,date=parseDate(get('date')),start=parseTime(get('start')),end=parseTime(get('end')),subject=optional(get('subject'),300),topic=optional(get('topic'),2000),content=optional(get('content'),8000),teacher=optional(get('teacher'),300),room=optional(get('room'),300),homework=optional(get('homework'),5000),activity=normalizeMode(get('mode'));const messages=[];if(!date)messages.push('Datum nicht erkannt');if(!start)messages.push('Beginn nicht erkannt');if(!end)messages.push('Ende nicht erkannt');if(start&&end&&end<=start)messages.push('Ende liegt nicht nach Beginn');if(!subject&&!topic&&!content)messages.push('Kein Fach/Thema/Inhalt erkannt');const status=messages.length?'error':'ready';if(status==='error')errors++;return{rowNo:index+2,raw:r,normalized:date&&start&&end?{date,starts_at:`${date}T${start}:00`,ends_at:`${date}T${end}:00`,subject,teacher,room,topic,content,homework,activity_type:activity,completed:String(get('status')||'').toLowerCase().match(/ja|yes|1|true|fertig|abgeschlossen/)?1:topic||content?1:0}:null,status,message:messages.join('; ')};});rowCount=rows.length;}else{rowCount=0;warnings=archiveOnly?1:0;}
  const course=courseId?await env.DB.prepare('SELECT start_date,end_date FROM courses WHERE tenant_id=? AND id=?').bind(tenantId,courseId).first<{start_date:string|null;end_date:string|null}>():null,startedMid=course?.start_date&&course.start_date<new Date().toISOString().slice(0,10)?1:0;await env.DB.prepare('INSERT INTO legacy_import_batches(id,tenant_id,course_id,resource_type,mode,original_name,source_file_id,source_sha256,status,row_count,warning_count,error_count,started_mid_course,notes,created_by,created_at,applied_at,error_message) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NULL,NULL)').bind(batchId,tenantId,courseId,resource,mode,file.name,stored.fileId,stored.hash,archiveOnly?'archived':'preview',rowCount,warnings,errors,startedMid,optional(form.get('notes'),5000),auth.userId,ts).run();for(const row of rows)await env.DB.prepare('INSERT INTO legacy_import_rows(batch_id,row_no,row_json,normalized_json,status,message,target_type,target_id) VALUES(?,?,?,?,?,?,NULL,NULL)').bind(batchId,row.rowNo,JSON.stringify(row.raw),row.normalized?JSON.stringify(row.normalized):null,row.status,row.message||null).run();await audit(env.DB,auth.userId,'education.legacy_import_preview',tenantId,courseId||undefined,'legacy_import_batch',batchId,{resource,mode,rowCount,errors,archiveOnly});return{batch_id:batchId,archive_only:archiveOnly,row_count:rowCount,warning_count:warnings,error_count:errors,sample:rows.slice(0,20).map(x=>({row:x.rowNo,status:x.status,message:x.message,normalized:x.normalized})),source_sha256:stored.hash};}

export async function applyLegacyClassbookImport(env:Env,auth:CoreAuthContext,tenantId:string,batchId:string){requireManage(auth);const batch=await env.DB.prepare("SELECT * FROM legacy_import_batches WHERE tenant_id=? AND id=? AND resource_type='classbook'").bind(tenantId,batchId).first<Record<string,unknown>>();if(!batch)throw new Error('LEGACY_IMPORT_NOT_FOUND');if(batch.status==='applied')return{applied:Number(batch.row_count||0),already_applied:true};if(batch.status==='archived')throw new Error('LEGACY_IMPORT_ARCHIVE_ONLY');if(Number(batch.error_count||0)>0)throw new Error('LEGACY_IMPORT_HAS_ERRORS');const courseId=String(batch.course_id||'');courseScope(auth,courseId);const rows=(await env.DB.prepare("SELECT row_no,normalized_json FROM legacy_import_rows WHERE batch_id=? AND status='ready' ORDER BY row_no").bind(batchId).all<{row_no:number;normalized_json:string}>()).results??[];let applied=0;for(const r of rows){const x=JSON.parse(r.normalized_json) as any,sourceRef=`legacy:${batchId}:${r.row_no}`;let session=await env.DB.prepare("SELECT id FROM attendance_sessions WHERE tenant_id=? AND course_id=? AND source='import' AND source_ref=?").bind(tenantId,courseId,sourceRef).first<{id:string}>();const sessionId=session?.id||id('ats_'),ts=nowIso();if(!session)await env.DB.prepare("INSERT INTO attendance_sessions(id,tenant_id,course_id,session_date,starts_at,ends_at,subject,room,instructor_text,delivery_mode,status,source,source_ref,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,'held','import',?,?,?,?)").bind(sessionId,tenantId,courseId,x.date,x.starts_at,x.ends_at,x.subject,x.room,x.teacher,x.activity_type==='live_remote'?'remote':x.activity_type==='hybrid_live'?'hybrid':'onsite',sourceRef,auth.userId,ts,ts).run();await env.DB.prepare('INSERT INTO classbook_entries(session_id,tenant_id,course_id,topic,content_summary,homework_summary,substitute_instructor,completed,updated_by,updated_at) VALUES(?,?,?,?,?,?,NULL,?,?,?) ON CONFLICT(session_id) DO UPDATE SET topic=excluded.topic,content_summary=excluded.content_summary,homework_summary=excluded.homework_summary,completed=excluded.completed,updated_by=excluded.updated_by,updated_at=excluded.updated_at').bind(sessionId,tenantId,courseId,x.topic,x.content,x.homework,x.completed?1:0,auth.userId,ts).run();await env.DB.prepare('INSERT INTO instruction_activity_details(id,tenant_id,course_id,lesson_id,session_id,activity_type,location_label,supervision_mode,attendance_expected,evidence_required,task_text,expected_outcome,safety_notes,external_contact,created_by,created_at,updated_at) VALUES(?,?,?,NULL,?,?,?,?,1,0,NULL,NULL,NULL,NULL,?,?,?) ON CONFLICT(tenant_id,session_id) DO UPDATE SET activity_type=excluded.activity_type,location_label=excluded.location_label,updated_at=excluded.updated_at').bind(id('act_'),tenantId,courseId,sessionId,x.activity_type,x.room,x.activity_type.startsWith('self_study')?'self_directed':'instructor',auth.userId,ts,ts).run();await env.DB.prepare("UPDATE legacy_import_rows SET status='applied',target_type='attendance_session',target_id=? WHERE batch_id=? AND row_no=?").bind(sessionId,batchId,r.row_no).run();applied++;}const ts=nowIso();await env.DB.prepare("UPDATE legacy_import_batches SET status='applied',applied_at=? WHERE tenant_id=? AND id=?").bind(ts,tenantId,batchId).run();await audit(env.DB,auth.userId,'education.legacy_import_applied',tenantId,courseId,'legacy_import_batch',batchId,{applied});return{applied};}

export async function listLegacyImports(env:Env,auth:CoreAuthContext,tenantId:string){requireManage(auth);return(await env.DB.prepare('SELECT * FROM legacy_import_batches WHERE tenant_id=? ORDER BY created_at DESC LIMIT 300').bind(tenantId).all<Record<string,unknown>>()).results??[];}

export async function runLearningOperationsAutomation(env:Env){const pending=(await env.DB.prepare("SELECT r.id,r.tenant_id,r.signer_user_id,d.course_id,d.title FROM signature_requests r JOIN signature_documents d ON d.id=r.document_id AND d.tenant_id=r.tenant_id WHERE r.status='pending' AND r.signer_user_id IS NOT NULL AND (r.reminder_after IS NULL OR r.reminder_after<=?) AND (r.due_at IS NULL OR r.due_at>=datetime('now','-30 day')) LIMIT 400").bind(nowIso()).all<Record<string,unknown>>()).results??[];for(const r of pending){const duplicate=await env.DB.prepare("SELECT 1 FROM notifications WHERE tenant_id=? AND user_id=? AND type='signature_reminder' AND body LIKE ? AND created_at>=datetime('now','-2 day') LIMIT 1").bind(r.tenant_id,r.signer_user_id,`%${r.id}%`).first();if(duplicate)continue;await env.DB.prepare("INSERT INTO notifications(id,tenant_id,course_id,user_id,type,title,body,read_at,created_at) VALUES(?,?,?,?, 'signature_reminder','Digitale Bestätigung offen',?,NULL,?)").bind(id('not_'),r.tenant_id,r.course_id||null,r.signer_user_id,`${r.title} · Vorgang ${r.id}`,nowIso()).run();}
  await env.DB.prepare("UPDATE teacher_qualifications SET status='expired',updated_at=? WHERE status='valid' AND valid_until IS NOT NULL AND valid_until<date('now')").bind(nowIso()).run().catch(()=>undefined);
}
